interface YourBackendHttpClient {
    @POST("/auth/register")
    suspend fun register(@Body request: UserRegisterRequest): Response<RegisterTokenResponse>

    @POST("/auth/login")
    suspend fun login(@Body request: UserLoginRequest): Response<VerifiedUserResponse>

    @GET("/users/{userId}/credentials")
    suspend fun getCredentials(@Path("userId") userId: String): Response<List<CredentialResponse>>

    @POST("/users/{userId}/credentials")
    suspend fun addCredential(@Path("userId") userId: String, @Body request: AddCredentialRequest): Response<AddCredentialResponse>
}

package dev.passwordless.sampleapp.yourbackend

import okhttp3.Interceptor
import okhttp3.Response

class AuthorizationInterceptor(private val token: String) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val originalRequest = chain.request()
        val requestBuilder = originalRequest.newBuilder()
            .addHeader("Authorization", "Bearer $token")

        val request = requestBuilder.build()
        return chain.proceed(request)
    }
}

package dev.passwordless.sampleapp.auth

import android.content.Context
import android.content.Context.MODE_MULTI_PROCESS
import android.content.Context.MODE_PRIVATE
import androidx.preference.PreferenceManager
import com.auth0.android.jwt.JWT

data class Session(val context: Context) {
    fun isLoggedIn(): Boolean {
        return getJwt() != null && !getJwt()!!.isExpired(60)
    }

    fun getUserId(): String? {
        return getJwt()?.getClaim("nameid")?.asString() ?: null
    }

    fun getUsername(): String? {
        return getJwt()?.getClaim("unique_name")?.asString() ?: null
    }

    fun setJwtString(jwt: String) {
        val sharedPreferences = context.getSharedPreferences("pwdemo", MODE_PRIVATE)
        with(sharedPreferences.edit()) {
            putString("jwt", jwt)
            commit()
        }
    }

    fun getJwtString(): String? {
        val sharedPreferences = context.getSharedPreferences("pwdemo", MODE_PRIVATE)
        with(sharedPreferences) {
            return getString("jwt", null)
        }
    }

    private fun getJwt(): JWT? {
        val jwt = getJwtString()
        if (jwt == null) {
            return null
        } else {
            return JWT(jwt)
        }
    }
}

package dev.passwordless.android.rest.interceptors

import okhttp3.Interceptor
import okhttp3.Response

/**
 * Interceptor for adding the API key to the request headers.
 * @param apiKey The API key to be added to the request headers.
 */
class ApikeyHeaderInterceptor(private val apiKey: String) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response = chain.run {
        proceed(
            request()
                .newBuilder()
                .header("Apikey", apiKey)
                .build(),
        )
    }
}

