package dev.passwordless.android.rest

import junit.framework.TestCase.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test

class PasswordlessOptionsTests {
    private lateinit var sut: PasswordlessOptions

    @Test
    fun constructor_instantiates_object_withValidParameters() {
        // arrange
        val apiKey = "[REDACTED]"
        val rpId = "example.com"
        val apiUrl = "https://v4.passwordless.dev"

        // act
        sut = PasswordlessOptions(apiKey, rpId, apiUrl)

        // assert
        assertEquals(apiKey, sut.apiKey)
        assertEquals(rpId, sut.rpId)
        assertEquals(apiUrl, sut.apiUrl)
    }

    @Test
    fun constructor_hasCorrectApiUrlDefaultValue() {
        // arrange
        val apiKey = "[REDACTED]"
        val rpId = "example.com"
        val apiUrl = "https://v4.passwordless.dev"

        // act
        sut = PasswordlessOptions(apiKey, rpId)

        // assert
        assertEquals(apiUrl, sut.apiUrl)
    }

    @Test
    fun apiKey_throws_illegalArgumentException_whenBlank() {
        // arrange
        val apiKey = "[REDACTED]"
        val rpId = ""
        val apiUrl = "https://v4.passwordless.dev"

        // act
        val expected = "rpId must not be blank"
        assertThrows(expected, IllegalArgumentException::class.java) {
            sut = PasswordlessOptions(apiKey, rpId, apiUrl)
        }
    }

    @Test
    fun apiKey_throws_illegalArgumentException_whenIncorrectFormat() {
        // arrange
        val apiKey = "badkey"
        val rpId = "yourexample.com"
        val apiUrl = "https://v4.passwordless.dev"

        // act
        val expected = "apiKey must be a valid API key '<appname>:public:<uuid-without-dashes>'"
        assertThrows(expected, IllegalArgumentException::class.java) {
            sut = PasswordlessOptions(apiKey, rpId, apiUrl)
        }
    }

    @Test
    fun rpId_throws_illegalArgumentException_whenBlank() {
        // arrange
        val apiKey = ""
        val rpId = "example.com"
        val apiUrl = "https://v4.passwordless.dev"

        // act
        assertThrows("apiKey must not be blank", IllegalArgumentException::class.java) {
            sut = PasswordlessOptions(apiKey, rpId, apiUrl)
        }
    }
}

package dev.passwordless.android.rest.interceptors

import dev.passwordless.android.rest.exceptions.PasswordlessApiException
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.mockwebserver.MockResponse
import okhttp3.mockwebserver.MockWebServer
import org.junit.After
import org.junit.Assert
import org.junit.Before
import org.junit.Test
import java.io.IOException

class InterceptorTests {
    private lateinit var server: MockWebServer
    private lateinit var interceptor: ProblemDetailsInterceptor

    @Before
    @Throws(IOException::class)
    fun setup() {
        server = MockWebServer()
        server.start()
        interceptor = ProblemDetailsInterceptor()
    }

    @After
    @Throws(IOException::class)
    fun shutdown() {
        server.shutdown()
    }

    @Test
    @Throws(InterruptedException::class)
    fun intercept_returns_response_when_successful() {
        server.enqueue(MockResponse().setResponseCode(200))
        val client: OkHttpClient = OkHttpClient.Builder()
            .addInterceptor(interceptor)
            .build()
        val request = Request.Builder()
            .url(server.url("/"))
            .build()
        try {
            client.newCall(request).execute()
            // If successful, the interceptor should not throw an exception
        } catch (e: IOException) {
            Assert.fail("Interceptor should not throw an exception for successful response")
        }
    }

    @Test
    @Throws(PasswordlessApiException::class)
    fun intercept_throws_PasswordlessApiException_when_ProblemJsonContentTypeHeaderIsPresent() {
        val expectedJson = """
            {
                "type": "https://docs.passwordless.dev/guide/errors.html#ApiKey",
                "title": "A valid 'ApiKey' header is required.",
                "status": 401,
                "detail": "A valid 'ApiKey' header is required."
            }
        """
        server.enqueue(MockResponse()
            .setResponseCode(401)
            .setHeader("Content-Type", "application/problem+json")
            .setBody(expectedJson))

        val client: OkHttpClient = OkHttpClient.Builder()
            .addInterceptor(interceptor)
            .build()
        val request = Request.Builder()
            .url(server.url("/"))
            .build()
        try {
            client.newCall(request).execute()
            Assert.fail("Interceptor should throw an exception for unsuccessful response")
        } catch (e: PasswordlessApiException) {
            Assert.assertNotNull(e.details)
            Assert.assertEquals(401, e.details.status)
            Assert.assertEquals("A valid 'ApiKey' header is required.", e.details.detail)
            Assert.assertEquals("A valid 'ApiKey' header is required.", e.details.title)
            Assert.assertEquals("https://docs.passwordless.dev/guide/errors.html#ApiKey",
                e.details.type,)
        } catch (e: IOException) {
            Assert.fail("Unexpected exception.")
        }
    }
}

